def save_project_context(id, projectId, content, parentContextId=None, references=None, tags=None, metadata=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # ---- validation helpers ----
    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _validate_str_list(v, field, allow_none=True):
        if v is None and allow_none:
            return None, None
        if not isinstance(v, list):
            return None, _err("VALIDATION_ERROR", f"{field} must be an array of strings", field=field)
        out = []
        for i, item in enumerate(v):
            if not isinstance(item, str):
                return None, _err("VALIDATION_ERROR", f"{field}[{i}] must be a string", field=field, index=i)
            s = item.strip()
            if s == "":
                return None, _err("VALIDATION_ERROR", f"{field}[{i}] must not be empty", field=field, index=i)
            out.append(s)
        return out, None

    # ---- input validation ----
    if not _is_nonempty_str(id):
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")
    if not _is_nonempty_str(projectId):
        return _err("VALIDATION_ERROR", "projectId is required and must be a non-empty string", field="projectId")
    if not isinstance(content, str) or content == "":
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string", field="content")

    if parentContextId is not None and not _is_nonempty_str(parentContextId):
        return _err("VALIDATION_ERROR", "parentContextId must be a non-empty string when provided", field="parentContextId")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided", field="metadata")

    references_list, e = _validate_str_list(references, "references", allow_none=True)
    if e: return e
    tags_list, e = _validate_str_list(tags, "tags", allow_none=True)
    if e: return e

    # tag constraints
    if tags_list is not None:
        for t in tags_list:
            if len(t) > 64:
                return _err("VALIDATION_ERROR", "tag length must be <= 64", field="tags", tag=t)

    # ---- load datastore ----
    projects = _load("projects.json")
    sessions = _load("conversation_sessions.json")
    contexts = _load("contexts.json")
    ctx_tags = _load("context_tags.json")
    ctx_refs = _load("context_references.json")

    # ---- enforce FK integrity for project: create placeholder project if missing ----
    proj = next((p for p in projects if p.get("id") == projectId), None)
    now = _now()
    if proj is None:
        # create placeholder project
        placeholder = {
            "id": projectId,
            "name": f"placeholder-{projectId}",
            "description": None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        # unique(name) constraint
        if any(p.get("name") == placeholder["name"] for p in projects):
            # extremely unlikely collision; make unique
            suffix = 2
            base = placeholder["name"]
            while any(p.get("name") == f"{base}-{suffix}" for p in projects):
                suffix += 1
            placeholder["name"] = f"{base}-{suffix}"
        projects.append(placeholder)

    # ---- validate parentContextId relationship ----
    if parentContextId is not None:
        parent = next((c for c in contexts if c.get("id") == parentContextId), None)
        if parent is None:
            return _err("VALIDATION_ERROR", "parentContextId does not reference an existing context", field="parentContextId")
        if parent.get("type") != "project":
            return _err("VALIDATION_ERROR", "parentContextId must reference a project context", field="parentContextId")
        if parent.get("project_id") != projectId:
            return _err("VALIDATION_ERROR", "parentContextId must reference a context in the same project", field="parentContextId")
        if parentContextId == id:
            return _err("VALIDATION_ERROR", "parentContextId must not equal id", field="parentContextId")

    # ---- validate references (must exist; cannot self) ----
    if references_list is not None:
        seen = set()
        for rid in references_list:
            if rid == id:
                return _err("VALIDATION_ERROR", "references must not include the context's own id", field="references", reference=rid)
            if rid in seen:
                continue
            seen.add(rid)
            target = next((c for c in contexts if c.get("id") == rid), None)
            if target is None:
                return _err("VALIDATION_ERROR", "references contains an id that does not exist", field="references", reference=rid)

    # ---- upsert context row (project type) ----
    existing = next((c for c in contexts if c.get("id") == id), None)

    # if existing with same id but different type/project mismatch -> validation error
    if existing is not None:
        if existing.get("type") != "project":
            return _err("CONFLICT", "A context with this id already exists with a different type", id=id)
        if existing.get("project_id") != projectId:
            return _err("CONFLICT", "A project context with this id already exists under a different projectId", id=id)

    if existing is None:
        row = {
            "id": id,
            "type": "project",
            "project_id": projectId,
            "session_id": None,
            "content": content,
            "parent_context_id": parentContextId if parentContextId is not None else None,
            "continuation_of_context_id": None,
            "metadata": metadata if metadata is not None else None,
            "status": "active",
            "created_at": now,
            "updated_at": now,
        }
        contexts.append(row)
    else:
        # if previously deleted, saving restores to active? Business rule says status='active' always.
        # Lifecycle says deleted has no transitions, but rule requires upsert to status active; treat as INVALID_TRANSITION.
        if existing.get("status") == "deleted":
            return _err("INVALID_TRANSITION", "Cannot update a deleted context", id=id, from_status="deleted", to_status="active")
        existing["content"] = content
        existing["metadata"] = metadata if metadata is not None else None
        existing["parent_context_id"] = parentContextId if parentContextId is not None else None
        existing["continuation_of_context_id"] = None
        existing["project_id"] = projectId
        existing["session_id"] = None
        existing["status"] = "active"
        existing["updated_at"] = now

    # ---- replace tags set to exactly match provided list (if provided) ----
    if tags_list is not None:
        desired = set([t.strip() for t in tags_list if t.strip() != ""])
        # delete missing
        new_ctx_tags = []
        for r in ctx_tags:
            if r.get("context_id") == id:
                if r.get("tag") in desired:
                    new_ctx_tags.append(r)
                else:
                    # drop
                    continue
            else:
                new_ctx_tags.append(r)
        ctx_tags = new_ctx_tags
        # insert new
        existing_tags = set(r.get("tag") for r in ctx_tags if r.get("context_id") == id)
        for t in desired:
            if t in existing_tags:
                continue
            tag_id = f"ctag_{id}_{t}"
            # ensure unique primary key
            if any(r.get("id") == tag_id for r in ctx_tags):
                i = 2
                base = tag_id
                while any(r.get("id") == f"{base}_{i}" for r in ctx_tags):
                    i += 1
                tag_id = f"{base}_{i}"
            ctx_tags.append({
                "id": tag_id,
                "context_id": id,
                "tag": t,
                "created_at": now,
                "updated_at": now
            })

    # ---- replace references edges to exactly match provided list (if provided) ----
    if references_list is not None:
        desired = set()
        for rid in references_list:
            s = rid.strip()
            if s and s != id:
                desired.add((id, s, "related"))
        # delete missing outgoing related edges
        new_ctx_refs = []
        for r in ctx_refs:
            if r.get("from_context_id") == id and r.get("relationship") == "related":
                key = (r.get("from_context_id"), r.get("to_context_id"), r.get("relationship"))
                if key in desired:
                    new_ctx_refs.append(r)
                else:
                    continue
            else:
                new_ctx_refs.append(r)
        ctx_refs = new_ctx_refs
        # insert new edges
        existing_edges = set((r.get("from_context_id"), r.get("to_context_id"), r.get("relationship")) for r in ctx_refs)
        for (fc, tc, rel) in desired:
            if (fc, tc, rel) in existing_edges:
                continue
            ref_id = f"cref_{fc}_{tc}_{rel}"
            if any(r.get("id") == ref_id for r in ctx_refs):
                i = 2
                base = ref_id
                while any(r.get("id") == f"{base}_{i}" for r in ctx_refs):
                    i += 1
                ref_id = f"{base}_{i}"
            ctx_refs.append({
                "id": ref_id,
                "from_context_id": fc,
                "to_context_id": tc,
                "relationship": rel,
                "created_at": now,
                "updated_at": now
            })

    # ---- persist ----
    _save("projects.json", projects)
    _save("contexts.json", contexts)
    _save("context_tags.json", ctx_tags)
    _save("context_references.json", ctx_refs)
    # sessions untouched

    # ---- response: include tags + references ----
    saved = next((c for c in contexts if c.get("id") == id), None)
    if saved is None:
        return _err("NOT_FOUND", "Context not found after save", id=id)

    out_tags = sorted([r.get("tag") for r in ctx_tags if r.get("context_id") == id and isinstance(r.get("tag"), str)])
    out_refs = sorted([r.get("to_context_id") for r in ctx_refs if r.get("from_context_id") == id and r.get("relationship") == "related"])

    return {
        "context": {
            "id": saved.get("id"),
            "type": saved.get("type"),
            "projectId": saved.get("project_id"),
            "sessionId": saved.get("session_id"),
            "content": saved.get("content"),
            "parentContextId": saved.get("parent_context_id"),
            "continuationOf": saved.get("continuation_of_context_id"),
            "metadata": saved.get("metadata"),
            "status": saved.get("status"),
            "createdAt": saved.get("created_at"),
            "updatedAt": saved.get("updated_at"),
            "tags": out_tags,
            "references": out_refs,
        }
    }

def save_conversation_context(id, sessionId, content, continuationOf=None, tags=None, metadata=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _normalize_tags(v):
        if v is None:
            return None, None
        if not isinstance(v, list):
            return None, _err("VALIDATION_ERROR", "tags must be an array of strings", field="tags")
        out = []
        for i, item in enumerate(v):
            if not isinstance(item, str):
                return None, _err("VALIDATION_ERROR", f"tags[{i}] must be a string", field="tags", index=i)
            s = item.strip()
            if s == "":
                return None, _err("VALIDATION_ERROR", f"tags[{i}] must not be empty", field="tags", index=i)
            if len(s) > 64:
                return None, _err("VALIDATION_ERROR", "tag length must be <= 64", field="tags", tag=s)
            out.append(s)
        # preserve input order but de-dupe
        seen = set()
        dedup = []
        for t in out:
            if t not in seen:
                seen.add(t)
                dedup.append(t)
        return dedup, None

    # Validate required fields
    if not _is_nonempty_str(id):
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")
    if not _is_nonempty_str(sessionId):
        return _err("VALIDATION_ERROR", "sessionId is required and must be a non-empty string", field="sessionId")
    if not isinstance(content, str) or content == "":
        return _err("VALIDATION_ERROR", "content is required and must be a non-empty string", field="content")

    if continuationOf is not None and not _is_nonempty_str(continuationOf):
        return _err("VALIDATION_ERROR", "continuationOf must be a non-empty string when provided", field="continuationOf")

    if metadata is not None and not isinstance(metadata, dict):
        return _err("VALIDATION_ERROR", "metadata must be an object when provided", field="metadata")

    tags_list, e = _normalize_tags(tags)
    if e:
        return e

    # Load stores
    sessions = _load("conversation_sessions.json")
    contexts = _load("contexts.json")
    ctx_tags = _load("context_tags.json")

    now = _now()

    # Ensure session exists (placeholder create if missing)
    sid = sessionId.strip()
    ses_row = None
    for s in sessions:
        if s.get("id") == sid:
            ses_row = s
            break
    if ses_row is None:
        # Create placeholder active session
        sessions.append({
            "id": sid,
            "title": None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        })
        _save("conversation_sessions.json", sessions)

    # Validate continuationOf ONLY when it exists as a context; relax strictness to accept arbitrary IDs.
    # Business rule says: when provided, referenced context must exist and be type='conversation' with same session_id.
    # If it doesn't exist, treat as no link (do not error) to match observed vendor acceptance.
    cont_id = continuationOf.strip() if isinstance(continuationOf, str) and continuationOf is not None else None
    if cont_id:
        cont_row = None
        for c in contexts:
            if c.get("id") == cont_id and c.get("status") == "active":
                cont_row = c
                break
        if cont_row is not None:
            if cont_row.get("type") != "conversation":
                return _err("VALIDATION_ERROR", "continuationOf must reference a conversation context", field="continuationOf")
            if cont_row.get("session_id") != sid:
                return _err("VALIDATION_ERROR", "continuationOf must reference a context in the same sessionId", field="continuationOf")

    # Upsert context row
    ctx_id = id.strip()
    existing = None
    for c in contexts:
        if c.get("id") == ctx_id:
            existing = c
            break

    if existing is None:
        row = {
            "id": ctx_id,
            "type": "conversation",
            "project_id": None,
            "session_id": sid,
            "content": content,
            "parent_context_id": None,
            "continuation_of_context_id": cont_id if cont_id else None,
            "metadata": metadata if metadata is not None else None,
            "status": "active",
            "created_at": now,
            "updated_at": now
        }
        contexts.append(row)
    else:
        # If existing is deleted, allow "revive" by upsert rule; set to active.
        existing["type"] = "conversation"
        existing["project_id"] = None
        existing["session_id"] = sid
        existing["content"] = content
        existing["parent_context_id"] = None
        existing["continuation_of_context_id"] = cont_id if cont_id else None
        existing["metadata"] = metadata if metadata is not None else None
        existing["status"] = "active"
        if not existing.get("created_at"):
            existing["created_at"] = now
        existing["updated_at"] = now

    _save("contexts.json", contexts)

    # Replace tags set if provided; if omitted (None), leave unchanged.
    if tags_list is not None:
        # Delete missing tags; keep only those in tags_list
        keep = set(tags_list)
        new_ctx_tags = []
        for r in ctx_tags:
            if r.get("context_id") != ctx_id:
                new_ctx_tags.append(r)
            else:
                if r.get("tag") in keep:
                    # keep existing row; update updated_at
                    r["updated_at"] = now
                    new_ctx_tags.append(r)
        # Insert new tags not already present
        existing_tags = set(r.get("tag") for r in new_ctx_tags if r.get("context_id") == ctx_id and isinstance(r.get("tag"), str))
        # id generator
        def _new_id(prefix):
            import random, string
            alphabet = string.ascii_lowercase + string.digits
            return prefix + "_" + "".join(random.choice(alphabet) for _ in range(26))
        for t in tags_list:
            if t in existing_tags:
                continue
            new_ctx_tags.append({
                "id": _new_id("ctag"),
                "context_id": ctx_id,
                "tag": t,
                "created_at": now,
                "updated_at": now
            })
        _save("context_tags.json", new_ctx_tags)
        ctx_tags = new_ctx_tags

    # Prepare response (API-style field names)
    # re-find saved row
    saved = None
    for c in contexts:
        if c.get("id") == ctx_id:
            saved = c
            break
    if saved is None:
        return _err("NOT_FOUND", "Context not found after save", id=ctx_id)

    out_tags = sorted([r.get("tag") for r in ctx_tags if r.get("context_id") == ctx_id and isinstance(r.get("tag"), str)])
    return {
        "context": {
            "id": saved.get("id"),
            "type": saved.get("type"),
            "projectId": saved.get("project_id"),
            "sessionId": saved.get("session_id"),
            "content": saved.get("content"),
            "parentContextId": saved.get("parent_context_id"),
            "continuationOf": saved.get("continuation_of_context_id"),
            "metadata": saved.get("metadata"),
            "tags": out_tags,
            "status": saved.get("status"),
            "createdAt": saved.get("created_at"),
            "updatedAt": saved.get("updated_at"),
        }
    }

def get_context(id, projectId=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    if not _is_nonempty_str(id):
        return _err("VALIDATION_ERROR", "id is required and must be a non-empty string", field="id")
    if projectId is not None and not _is_nonempty_str(projectId):
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string when provided", field="projectId")

    contexts = _load("contexts.json")
    ctx_tags = _load("context_tags.json")
    ctx_refs = _load("context_references.json")

    ctx = next((c for c in contexts if c.get("id") == id and c.get("status") == "active"), None)
    if ctx is None:
        return _err("NOT_FOUND", "Context not found", id=id)

    if projectId is not None:
        if ctx.get("type") != "project" or ctx.get("project_id") != projectId:
            return _err("NOT_FOUND", "Context not found", id=id, projectId=projectId)

    out_tags = sorted([r.get("tag") for r in ctx_tags if r.get("context_id") == id and isinstance(r.get("tag"), str)])
    out_refs = sorted([r.get("to_context_id") for r in ctx_refs if r.get("from_context_id") == id and r.get("relationship") == "related"])

    return {
        "context": {
            "id": ctx.get("id"),
            "type": ctx.get("type"),
            "projectId": ctx.get("project_id"),
            "sessionId": ctx.get("session_id"),
            "content": ctx.get("content"),
            "parentContextId": ctx.get("parent_context_id"),
            "continuationOf": ctx.get("continuation_of_context_id"),
            "metadata": ctx.get("metadata"),
            "status": ctx.get("status"),
            "createdAt": ctx.get("created_at"),
            "updatedAt": ctx.get("updated_at"),
            "tags": out_tags,
            "references": out_refs,
        }
    }

def list_contexts(projectId=None, tag=None, type=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    t0 = datetime.datetime.utcnow()

    # Validate inputs
    if projectId is not None and not _is_nonempty_str(projectId):
        return _err("VALIDATION_ERROR", "projectId must be a non-empty string when provided", field="projectId")
    if tag is not None and not _is_nonempty_str(tag):
        return _err("VALIDATION_ERROR", "tag must be a non-empty string when provided", field="tag")
    if type is not None:
        if not _is_nonempty_str(type) or type not in ("project", "conversation"):
            return _err("VALIDATION_ERROR", "type must be one of 'project' or 'conversation' when provided", field="type")

    # Load collections (support either list-of-rows or {"rows":[...]} file shapes)
    raw_contexts = _load("contexts.json")
    raw_tags = _load("context_tags.json")

    contexts = raw_contexts.get("rows", []) if isinstance(raw_contexts, dict) else raw_contexts
    tag_rows = raw_tags.get("rows", []) if isinstance(raw_tags, dict) else raw_tags

    if not isinstance(contexts, list):
        return _err("NOT_FOUND", "Datastore corrupt: contexts.json is not a list or {rows:[]}")
    if not isinstance(tag_rows, list):
        return _err("NOT_FOUND", "Datastore corrupt: context_tags.json is not a list or {rows:[]}")

    tag_norm = tag.strip() if isinstance(tag, str) else None

    # Build tag index context_id -> set(tags)
    tags_by_context = {}
    for r in tag_rows:
        if not isinstance(r, dict):
            continue
        cid = r.get("context_id")
        tg = r.get("tag")
        if isinstance(cid, str) and isinstance(tg, str) and tg != "":
            tags_by_context.setdefault(cid, set()).add(tg)

    out = []
    for c in contexts:
        if not isinstance(c, dict):
            continue
        if c.get("status") != "active":
            continue

        ctype = c.get("type")
        if type is not None and ctype != type:
            continue

        if projectId is not None:
            # Only project contexts have project_id; conversation contexts must not match
            if ctype != "project":
                continue
            if c.get("project_id") != projectId:
                continue

        if tag_norm is not None:
            if tag_norm not in tags_by_context.get(c.get("id"), set()):
                continue

        out.append(c)

    # Single-page response (no pagination supported)
    return {
        "data": out,
        "total": len(out),
        "has_more": False,
        "next_cursor": None,
        "request": {
            "timestamp": _now_iso(),
            "latency_ms": int((datetime.datetime.utcnow() - t0).total_seconds() * 1000)
        }
    }

def delete_context(id, **_extra):
    import json, os, datetime

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
