def save_project(id, name, description=None, status=None, **_extra):
    import json, os, datetime, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _is_nonempty_str(x):
        return isinstance(x, str) and x.strip() != ""

    def _valid_id(s):
        if not _is_nonempty_str(s):
            return False
        # permissive but disallow whitespace-only and control chars
        return re.match(r"^[^\s]+$", s.strip()) is not None

    started = datetime.datetime.utcnow()
    status_code = "ok"
    try:
        if not _valid_id(id):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Malformed id; expected non-empty token string.", field="id")
        if not _is_nonempty_str(name):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Malformed name; expected non-empty string.", field="name")
        if description is not None and not isinstance(description, str):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "description must be a string or null.", field="description")
        if status is not None:
            if not isinstance(status, str):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "status must be a string.", field="status")
            if status not in ("active", "archived", "deleted"):
                status_code = "VALIDATION_ERROR"
                return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "archived", "deleted"])

        projects = _load("projects.json")
        if not isinstance(projects, list):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Invalid stored projects data.")

        # Enforce unique(name)
        for p in projects:
            if not isinstance(p, dict):
                continue
            if p.get("name") == name and p.get("id") != id:
                status_code = "CONFLICT"
                return _err("CONFLICT", "Project name already exists.", field="name")

        now = _now()
        existing_idx = None
        existing = None
        for i, p in enumerate(projects):
            if isinstance(p, dict) and p.get("id") == id:
                existing_idx = i
                existing = p
                break

        if existing is None:
            # Create
            new_status = status if status is not None else "active"
            proj = {
                "id": id,
                "name": name,
                "description": description if description is not None else None,
                "status": new_status,
                "created_at": now,
                "updated_at": now,
            }
            projects.append(proj)
            _save("projects.json", projects)
            return {"project": proj}

        # Update
        cur_status = existing.get("status")
        if cur_status not in ("active", "archived", "deleted"):
            status_code = "VALIDATION_ERROR"
            return _err("VALIDATION_ERROR", "Stored project has invalid status.", field="status")

        new_status = cur_status if status is None else status
        if new_status != cur_status:
            transitions = {
                "active": {"archived", "deleted"},
                "archived": {"active", "deleted"},
                "deleted": set(),
            }
            if new_status not in transitions.get(cur_status, set()):
                status_code = "INVALID_TRANSITION"
                return _err(
                    "INVALID_TRANSITION",
                    "Invalid status transition.",
                    from_status=cur_status,
                    to_status=new_status,
                )

        existing["name"] = name
        existing["description"] = description if description is not None else None
        existing["status"] = new_status
        existing["updated_at"] = now
        projects[existing_idx] = existing
        _save("projects.json", projects)
        return {"project": existing}

    except (TypeError, ValueError) as e:
        status_code = "VALIDATION_ERROR"
        return _err("VALIDATION_ERROR", "Invalid input or stored data encountered.", detail=str(e))
    finally:
        try:
            logs = _load("request_logs.json")
            if isinstance(logs, list):
                ended = datetime.datetime.utcnow()
                latency_ms = int((ended - started).total_seconds() * 1000)
                logs.append(
                    {
                        "id": f"req_{int(ended.timestamp() * 1000)}_{os.getpid()}",
                        "endpoint": "save_project",
                        "timestamp": ended.replace(microsecond=0).isoformat() + "Z",
                        "status": status_code,
                        "latency_ms": latency_ms,
                    }
                )
                _save("request_logs.json", logs)
        except Exception:
            pass

