def list_projects(status=None, limit=None, cursor=None, **_extra):
    import json, os, datetime
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    # Validate inputs
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("active", "archived", "deleted"):
            return _err("VALIDATION_ERROR", "Invalid status filter.", field="status", allowed=["active", "archived", "deleted"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        return _err("VALIDATION_ERROR", "limit must be an integer.", field="limit")
    if limit < 1 or limit > 200:
        return _err("VALIDATION_ERROR", "limit out of range (1..200).", field="limit")

    # Cursor is opaque: accept either a project id (common) or a numeric offset string.
    start_after_id = None
    offset = None
    if cursor is not None:
        if not isinstance(cursor, str) or cursor.strip() == "":
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        c = cursor.strip()
        if c.isdigit():
            offset = int(c)
        else:
            start_after_id = c

    projects = _load("projects.json")
    if not isinstance(projects, list):
        return _err("VALIDATION_ERROR", "projects store is corrupt")

    # Filter
    filtered = []
    for p in projects:
        if not isinstance(p, dict):
            continue
        if status is not None and p.get("status") != status:
            continue
        filtered.append(p)

    # Sort by created_at then id for stable pagination
    def _dt(v):
        if isinstance(v, str):
            try:
                return datetime.datetime.fromisoformat(v.replace("Z", "+00:00"))
            except Exception:
                return datetime.datetime.min
        return datetime.datetime.min

    filtered.sort(key=lambda r: (_dt(r.get("created_at")), r.get("id") or ""))

    # Apply cursor
    start_index = 0
    if offset is not None:
        if offset < 0:
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")
        start_index = min(offset, len(filtered))
    elif start_after_id is not None:
        # If id not found, start at 0 (relax strictness; do not error)
        idx = None
        for i, p in enumerate(filtered):
            if p.get("id") == start_after_id:
                idx = i
                break
        start_index = (idx + 1) if idx is not None else 0

    page = filtered[start_index:start_index + limit]
    has_more = start_index + limit < len(filtered)
    next_cursor = None
    if has_more:
        # return an opaque but usable cursor: next numeric offset
        next_cursor = str(start_index + limit)

    # Map fields
    out = []
    for p in page:
        out.append({
            "id": p.get("id"),
            "name": p.get("name"),
            "description": p.get("description"),
            "status": p.get("status"),
            "createdAt": p.get("created_at"),
            "updatedAt": p.get("updated_at"),
        })

    return {
        "projects": out,
        "total": len(filtered),
        "has_more": has_more,
        "next_cursor": next_cursor
    }

def save_conversation_session(id, title, status=None, **_extra):
    import json, os, datetime, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0054000" if __import__("os").path.isdir("./environment_mix/0054000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # ---- observable dynamics: request log / quota/rate limit (if present) ----
    # If a request/audit/usage log exists, record every call and enforce rate/quota if configured there.
    log_file = None
    for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage.json", "usage_logs.json"):
        if os.path.exists(os.path.join(_DB, cand)):
            log_file = cand
            break

    def _append_log(status_text, error_code=None):
        if not log_file:
            return
        logs = _load(log_file)
        if not isinstance(logs, list):
            logs = []
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": f"req_{int(time.time()*1000)}",
            "service": "claude-server",
            "endpoint": "save_conversation_session",
            "timestamp": now,
            "status": status_text,
            "latency_ms": latency_ms,
        }
        if error_code:
            row["error_code"] = error_code
        logs.append(row)
        _save(log_file, logs)

    def _check_limits():
        # Best-effort: if a limits.json exists with simple structure, enforce it.
        limits_path = os.path.join(_DB, "limits.json")
        if not os.path.exists(limits_path) or not log_file:
            return None
        try:
            with open(limits_path, encoding="utf-8") as f:
                limits = json.load(f)
        except Exception:
            return None
        if not isinstance(limits, dict):
            return None

        logs = _load(log_file)
        if not isinstance(logs, list):
            return None

        rate = limits.get("rate_limit_per_minute")
        if isinstance(rate, int) and rate >= 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(seconds=60)
            cnt = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= rate:
                return _err("RATE_LIMIT", "Rate limit exceeded", limit=rate, window_seconds=60)

        quota = limits.get("quota_per_day")
        if isinstance(quota, int) and quota >= 0:
            cutoff = datetime.datetime.utcnow() - datetime.timedelta(days=1)
            cnt = 0
            for r in logs:
                ts = r.get("timestamp")
                if isinstance(ts, str):
                    try:
                        dt = datetime.datetime.fromisoformat(ts.replace("Z", "+00:00")).replace(tzinfo=None)
                    except Exception:
                        continue
                    if dt >= cutoff:
                        cnt += 1
            if cnt >= quota:
                return _err("QUOTA_EXCEEDED", "Daily quota exceeded", quota=quota, window_seconds=86400)

        return None

    limit_err = _check_limits()
    if limit_err:
        _append_log("error", error_code=limit_err["error"]["code"])
        return limit_err

    # ---- validation ----
    if not isinstance(id, str) or not id.strip():
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'id' is required and must be a non-empty string.", field="id")
    if not isinstance(title, str):
        _append_log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Field 'title' is required and must be a string.", field="title")

    allowed_status = {"active", "closed", "deleted"}
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Field 'status' must be one of: active, closed, deleted.", field="status")

    # ---- ambient auth ----
    # No explicit credentials exist in this tool signature; callers are already authenticated.
    # We only return UNAUTHORIZED if the datastore configuration explicitly requires it, but no such config is provided.
    # Therefore, proceed.

    sessions = _load("conversation_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # find existing
    existing = None
    existing_idx = None
    for i, s in enumerate(sessions):
        if isinstance(s, dict) and s.get("id") == id:
            existing = s
            existing_idx = i
            break

    transitions = {
        "active": {"closed", "deleted"},
        "closed": {"active", "deleted"},
        "deleted": set(),
    }

    if existing is None:
        # create
        new_status = status if status is not None else "active"
        if new_status not in allowed_status:
            _append_log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status")
        row = {
            "id": id,
            "title": title,
            "status": new_status,
            "created_at": now,
            "updated_at": now,
        }
        sessions.append(row)
        _save("conversation_sessions.json", sessions)
        _append_log("ok")
        return {"session": row}
    else:
        # update with lifecycle validation
        cur_status = existing.get("status")
        if cur_status not in allowed_status:
            # data corruption; refuse
            _append_log("error", error_code="CONFLICT")
            return _err("CONFLICT", "Existing session has invalid status in datastore.", id=id)

        new_status = status if status is not None else cur_status

        if new_status != cur_status:
            if new_status not in transitions.get(cur_status, set()):
                _append_log("error", error_code="VALIDATION_ERROR")
                return _err(
                    "VALIDATION_ERROR",
                    "Invalid status transition.",
                    from_status=cur_status,
                    to_status=new_status,
                    id=id,
                )

        # apply updates
        updated = dict(existing)
        updated["title"] = title
        updated["status"] = new_status
        updated["updated_at"] = now

        sessions[existing_idx] = updated
        _save("conversation_sessions.json", sessions)

        _append_log("ok")
        return {"session": updated}
